// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List the applications in the current organization
	// (GET /api/applications)
	ListApplications(w http.ResponseWriter, r *http.Request)
	// Register an application in the current organization
	// (POST /api/applications)
	CreateApplication(w http.ResponseWriter, r *http.Request)
	// Delete an application
	// (DELETE /api/applications/{id})
	DeleteApplication(w http.ResponseWriter, r *http.Request, id ApplicationID)
	// Get an application
	// (GET /api/applications/{id})
	GetApplication(w http.ResponseWriter, r *http.Request, id ApplicationID)
	// Update an application
	// (PATCH /api/applications/{id})
	UpdateApplication(w http.ResponseWriter, r *http.Request, id ApplicationID)
	// Deploy or upgrade an application (run the Helm rollout)
	// (POST /api/applications/{id}/rollout)
	RolloutApplication(w http.ResponseWriter, r *http.Request, id ApplicationID)
	// Uninstall an application's Helm release
	// (POST /api/applications/{id}/uninstall)
	UninstallApplication(w http.ResponseWriter, r *http.Request, id ApplicationID)
	// List the clusters registered to the current organization
	// (GET /api/clusters)
	ListClusters(w http.ResponseWriter, r *http.Request)
	// Register a Kubernetes cluster in the current organization
	// (POST /api/clusters)
	CreateCluster(w http.ResponseWriter, r *http.Request)
	// Delete a cluster
	// (DELETE /api/clusters/{id})
	DeleteCluster(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Get a cluster
	// (GET /api/clusters/{id})
	GetCluster(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Update a cluster (name and/or credentials)
	// (PATCH /api/clusters/{id})
	UpdateCluster(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Report the cluster credentials' access (capabilities)
	// (GET /api/clusters/{id}/capabilities)
	ListClusterCapabilities(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Generate an RBAC manifest for selected capabilities
	// (POST /api/clusters/{id}/capabilities/rbac)
	GenerateClusterRbac(w http.ResponseWriter, r *http.Request, id ClusterID)
	// List the Kubernetes namespaces of a cluster
	// (GET /api/clusters/{id}/namespaces)
	ListClusterNamespaces(w http.ResponseWriter, r *http.Request, id ClusterID)
	// List the Kubernetes nodes of a cluster
	// (GET /api/clusters/{id}/nodes)
	ListClusterNodes(w http.ResponseWriter, r *http.Request, id ClusterID)
	// List the Kubernetes pods of a cluster
	// (GET /api/clusters/{id}/pods)
	ListClusterPods(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Report a cluster's Tekton (job-running) status
	// (GET /api/clusters/{id}/tekton)
	GetClusterTekton(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Stop designating a cluster as a job runner
	// (POST /api/clusters/{id}/tekton/disable)
	DisableClusterTekton(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Designate a cluster to run jobs (install Tekton)
	// (POST /api/clusters/{id}/tekton/enable)
	EnableClusterTekton(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Submit a job (TaskRun) to a cluster
	// (POST /api/clusters/{id}/tekton/runs)
	SubmitClusterTektonRun(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Get a job (TaskRun) status
	// (GET /api/clusters/{id}/tekton/runs/{name})
	GetClusterTektonRun(w http.ResponseWriter, r *http.Request, id ClusterID, name string)
	// Remove a Spacefleet-managed Tekton install
	// (POST /api/clusters/{id}/tekton/uninstall)
	UninstallClusterTekton(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Upgrade a Spacefleet-managed Tekton install
	// (POST /api/clusters/{id}/tekton/upgrade)
	UpgradeClusterTekton(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Re-probe a cluster's connectivity
	// (POST /api/clusters/{id}/test)
	TestCluster(w http.ResponseWriter, r *http.Request, id ClusterID)
	// Liveness probe
	// (GET /api/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// List pending invitations for the current organization (admins only)
	// (GET /api/invitations)
	ListInvitations(w http.ResponseWriter, r *http.Request)
	// Invite a user to the current organization (admins only)
	// (POST /api/invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request)
	// Revoke a pending invitation (admins only)
	// (DELETE /api/invitations/{id})
	RevokeInvitation(w http.ResponseWriter, r *http.Request, id InvitationID)
	// Preview an invitation by its token
	// (GET /api/invites/{token})
	GetInvitation(w http.ResponseWriter, r *http.Request, token InviteToken)
	// Accept an invitation and join its organization
	// (POST /api/invites/{token}/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request, token InviteToken)
	// The current user and their organization memberships
	// (GET /api/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// List the members of the current organization
	// (GET /api/members)
	ListMembers(w http.ResponseWriter, r *http.Request)
	// Remove a member from the organization (admins only)
	// (DELETE /api/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, userId MemberUserID)
	// Change a member's role (admins only)
	// (PATCH /api/members/{userId})
	UpdateMemberRole(w http.ResponseWriter, r *http.Request, userId MemberUserID)
	// Create an organization (the caller becomes its first admin)
	// (POST /api/organizations)
	CreateOrganization(w http.ResponseWriter, r *http.Request)
	// Rename an organization (admins only)
	// (PATCH /api/organizations/{id})
	RenameOrganization(w http.ResponseWriter, r *http.Request, id OrganizationID)
}

